  "implementation": "def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    # Build members: dict community -> sorted list of nodes
    members = {}
    for node, comm in refinement.items():
        members.setdefault(comm, []).append(node)
    for comm in members:
        members[comm].sort()
    # Build aggregated edges
    agg = {}
    for u, v, w in edges:
        if u not in refinement or v not in refinement:
            raise ValueError('Edge endpoint not in refinement')
        cu = refinement[u]
        cv = refinement[v]
        # canonicalize unordered pair
        a, b = (cu, cv) if cu <= cv else (cv, cu)
        key = (a, b)
        agg[key] = agg.get(key, 0) + w
    # Convert to sorted list of [string, string, number]
    aggregate_edges = sorted([list(k) + [v] for k, v in agg.items()])
    return {
        'aggregate_edges': aggregate_edges,
        'members': members
    }"
